-- ============================================================
-- Seed default questions for game_id = 'truth-or-lie'
-- Safe to re-run: categories skip duplicates, questions only
-- insert if that category currently has zero questions.
-- ============================================================

insert into categories (game_id, name) values
  ('truth-or-lie', 'วิทยาศาสตร์'),
  ('truth-or-lie', 'สัตว์โลก'),
  ('truth-or-lie', 'อาหาร'),
  ('truth-or-lie', 'ประวัติศาสตร์'),
  ('truth-or-lie', 'ร่างกายมนุษย์'),
  ('truth-or-lie', 'อวกาศ'),
  ('truth-or-lie', 'ประวัติศาสตร์ไทย'),
  ('truth-or-lie', 'เทคโนโลยี')
on conflict (game_id, name) do nothing;

with cat as (
  select id, name from categories where game_id = 'truth-or-lie'
)
insert into questions (game_id, category_id, text, answer, explain)
select 'truth-or-lie', cat.id, v.text, v.answer, v.explain
from (values
    ('วิทยาศาสตร์', 'มนุษย์ใช้สมองแค่ 10% ของทั้งหมด ส่วนที่เหลือไม่ได้ใช้งาน', false, 'มั่ว! เป็นความเชื่อผิดๆ ที่แพร่หลายมาก จริงๆ แล้วสมองเกือบทุกส่วนถูกใช้งานตลอดเวลา แม้แต่ตอนนอนหลับ'),
    ('สัตว์โลก', 'ยีราฟนอนหลับวันละไม่ถึง 2 ชั่วโมง', true, 'จริง! ยีราฟเป็นสัตว์เลี้ยงลูกด้วยนมที่นอนน้อยที่สุด เฉลี่ยแค่ 30 นาที - 2 ชั่วโมงต่อวัน'),
    ('วิทยาศาสตร์', 'น้ำผึ้งแท้ไม่มีวันเน่าเสีย เก็บได้เป็นพันปี', true, 'จริง! เคยขุดพบน้ำผึ้งอายุกว่า 3,000 ปีในสุสานอียิปต์ที่ยังกินได้ เพราะน้ำผึ้งมีน้ำน้อยและเป็นกรดสูง แบคทีเรียอยู่ไม่ได้'),
    ('สัตว์โลก', 'ฉลามมีมาก่อนต้นไม้บนโลก', true, 'จริง! ฉลามมีมาแล้วกว่า 400 ล้านปีก่อน ก่อนต้นไม้ชนิดแรกจะวิวัฒนาการขึ้นมาบนโลกเสียอีก'),
    ('อาหาร', 'ช็อกโกแลตแท้ไม่มีคาเฟอีนเลย', false, 'มั่ว! โกโก้มีคาเฟอีนอยู่จริง เพียงแต่มีปริมาณน้อยกว่ากาแฟมาก'),
    ('ประวัติศาสตร์', 'กำแพงเมืองจีนสามารถมองเห็นได้ด้วยตาเปล่าจากอวกาศ', false, 'มั่ว! นักบินอวกาศหลายคนยืนยันว่ามองไม่เห็นด้วยตาเปล่าจากวงโคจรโลก เพราะกำแพงแคบเกินไปเมื่อเทียบกับระยะทาง'),
    ('ร่างกายมนุษย์', 'เล็บและผมยังคงยาวต่อไปได้หลังจากคนเสียชีวิตแล้ว', false, 'มั่ว! เป็นภาพลวงตา หลังตายผิวหนังจะหดตัวและแห้งลง ทำให้ดูเหมือนเล็บผมยาวขึ้น แต่จริงๆ ไม่มีการเจริญเติบโตใดๆ อีกแล้ว'),
    ('สัตว์โลก', 'นกกระจอกเทศไม่สามารถบินได้ แต่วิ่งเร็วกว่าม้า', true, 'จริง! นกกระจอกเทศวิ่งได้เร็วสูงสุดราว 70 กม./ชม. เร็วกว่าม้าแข่งหลายสายพันธุ์'),
    ('อวกาศ', 'ดาวศุกร์เป็นดาวเคราะห์ที่ร้อนที่สุดในระบบสุริยะ ร้อนกว่าดาวพุธที่อยู่ใกล้ดวงอาทิตย์มากกว่า', true, 'จริง! เพราะบรรยากาศหนาแน่นของดาวศุกร์เก็บกักความร้อนแบบเรือนกระจกสุดขั้ว อุณหภูมิพื้นผิวสูงกว่า 460°C มากกว่าดาวพุธเสียอีก'),
    ('ประวัติศาสตร์ไทย', 'คำว่า ''สยาม'' ถูกเปลี่ยนเป็น ''ประเทศไทย'' อย่างเป็นทางการครั้งแรกในสมัยรัชกาลที่ 8', true, 'จริง! เปลี่ยนชื่อประเทศจาก ''สยาม'' เป็น ''ไทย'' อย่างเป็นทางการเมื่อปี พ.ศ. 2482 ในรัฐบาลจอมพล ป. พิบูลสงคราม ช่วงรัชกาลที่ 8'),
    ('วิทยาศาสตร์', 'เพชรเกิดจากถ่านที่ถูกอัดแรงดันสูงเป็นเวลานาน', false, 'มั่ว! เพชรธรรมชาติเกิดจากคาร์บอนใต้เปลือกโลกลึกมาก ไม่ใช่ถ่านหิน ซึ่งเกิดจากซากพืชและมีอายุน้อยกว่าเพชรมาก'),
    ('สัตว์โลก', 'ผึ้งงานตายหลังจากต่อยแค่ครั้งเดียว', true, 'จริง! เข็มของผึ้งงานมีเงี่ยง ต่อยแล้วดึงออกจากผิวหนังคนไม่ได้ ทำให้อวัยวะภายในฉีกขาดและตายในเวลาต่อมา'),
    ('อาหาร', 'ผงชูรส (MSG) เป็นสารเคมีสังเคราะห์อันตรายที่ทำให้เกิดอาการแพ้รุนแรง', false, 'มั่ว! MSG คือเกลือของกรดกลูตามิกซึ่งพบตามธรรมชาติในอาหารหลายชนิด งานวิจัยจำนวนมากไม่พบหลักฐานว่าเป็นอันตรายในปริมาณที่บริโภคปกติ'),
    ('ร่างกายมนุษย์', 'ลิ้นของคนเรามีโซนรับรสเฉพาะส่วน เช่น หวานที่ปลายลิ้น ขมที่โคนลิ้นเท่านั้น', false, 'มั่ว! แผนที่ลิ้นแบบที่เคยเรียนกันเป็นความเข้าใจผิดจากงานวิจัยเก่าที่ตีความคลาดเคลื่อน จริงๆ ตุ่มรับรสทั่วลิ้นรับรสได้ทุกรสชาติ'),
    ('อวกาศ', 'ดวงจันทร์กำลังค่อยๆ เคลื่อนตัวห่างออกจากโลกทุกปี', true, 'จริง! ดวงจันทร์เคลื่อนห่างจากโลกประมาณ 3.8 ซม. ต่อปี จากแรงไทดัลระหว่างโลกกับดวงจันทร์'),
    ('ประวัติศาสตร์ไทย', 'วัดพระแก้วเป็นที่ประดิษฐานพระแก้วมรกตซึ่งแกะสลักจากมรกตแท้', false, 'มั่ว! แม้ชื่อจะเรียกว่า ''พระแก้วมรกต'' แต่จริงๆ แกะสลักจากหินหยกสีเขียว ไม่ใช่มรกตแท้'),
    ('สัตว์โลก', 'แมวไม่สามารถรับรสหวานได้เลย', true, 'จริง! แมวขาดยีนที่ใช้สร้างตัวรับรสหวานบนลิ้น ทำให้แมวชิมหวานไม่เป็น'),
    ('วิทยาศาสตร์', 'สายฟ้าไม่มีทางผ่าลงจุดเดียวกันสองครั้ง', false, 'มั่ว! ตึกสูงอย่าง Empire State Building ถูกฟ้าผ่าซ้ำจุดเดิมได้หลายสิบครั้งต่อปี'),
    ('เทคโนโลยี', 'อีเมลฉบับแรกของโลกถูกส่งก่อนอินเทอร์เน็ต (World Wide Web) จะถูกคิดค้นขึ้น', true, 'จริง! อีเมลฉบับแรกส่งเมื่อปี 1971 ส่วนเวิลด์ไวด์เว็บเพิ่งถูกคิดค้นในปี 1989'),
    ('ประวัติศาสตร์', 'พีระมิดแห่งกิซาสร้างเสร็จก่อนสัตว์แมมมอธตัวสุดท้ายจะสูญพันธุ์', true, 'จริง! แมมมอธกลุ่มสุดท้ายยังมีชีวิตอยู่จนถึงราว 1,650 ปีก่อนคริสตกาล หลังพีระมิดสร้างเสร็จไปแล้วกว่าพันปี'),
    ('ร่างกายมนุษย์', 'หัวใจของคนเราหยุดเต้นแค่เสี้ยววินาทีเวลาจาม', false, 'มั่ว! หัวใจแค่จังหวะการเต้นเปลี่ยนแปลงเล็กน้อย ไม่ได้หยุดเต้นจริงๆ'),
    ('สัตว์โลก', 'หมึกยักษ์ (ปลาหมึกออกโทปัส) มีหัวใจ 3 ดวง', true, 'จริง! สองดวงสูบฉีดเลือดไปที่เหงือก อีกดวงสูบฉีดไปเลี้ยงร่างกาย'),
    ('อาหาร', 'มะเขือเทศจัดเป็นผักตามหลักพฤกษศาสตร์', false, 'มั่ว! ตามหลักพฤกษศาสตร์มะเขือเทศเป็น ''ผลไม้'' เพราะเกิดจากรังไข่ของดอกและมีเมล็ดข้างใน'),
    ('อวกาศ', 'ดาวอังคารมีขนาดใหญ่กว่าโลก', false, 'มั่ว! ดาวอังคารมีขนาดเล็กกว่าโลกมาก เส้นผ่านศูนย์กลางประมาณครึ่งหนึ่งของโลกเท่านั้น'),
    ('ประวัติศาสตร์ไทย', 'สงครามที่สั้นที่สุดในประวัติศาสตร์โลกกินเวลาไม่ถึง 1 ชั่วโมง', true, 'จริง! สงครามอังกฤษ-แซนซิบาร์ ปี 1896 กินเวลาเพียงประมาณ 38-45 นาที'),
    ('วิทยาศาสตร์', 'เสียงเดินทางในน้ำได้เร็วกว่าในอากาศ', true, 'จริง! เสียงเดินทางในน้ำเร็วกว่าในอากาศประมาณ 4 เท่า'),
    ('สัตว์โลก', 'เต่ากระดองใหญ่ที่สุดในโลกสามารถถอดกระดองออกจากตัวได้เหมือนเสื้อผ้า', false, 'มั่ว! กระดองเต่าเชื่อมติดกับกระดูกสันหลังและซี่โครง ถอดออกไม่ได้'),
    ('เทคโนโลยี', 'รหัส QR Code ถูกคิดค้นขึ้นครั้งแรกเพื่อใช้ติดตามชิ้นส่วนรถยนต์ในโรงงาน', true, 'จริง! บริษัท Denso Wave ของญี่ปุ่นคิดค้น QR Code ขึ้นในปี 1994 เพื่อใช้ติดตามชิ้นส่วนรถยนต์'),
    ('ร่างกายมนุษย์', 'คนเราจามด้วยความเร็วเทียบเท่ารถแข่งฟอร์มูล่าวัน', false, 'มั่ว! ความเร็วละอองน้ำจากการจามจริงๆ อยู่ราว 150-160 กม./ชม. ไม่ถึงระดับรถ F1'),
    ('ประวัติศาสตร์', 'นโปเลียน โบนาปาร์ต มีส่วนสูงเตี้ยกว่าค่าเฉลี่ยชายฝรั่งเศสในยุคเดียวกันมาก', false, 'มั่ว! นโปเลียนสูงประมาณ 168-170 ซม. ใกล้เคียงหรือสูงกว่าค่าเฉลี่ยชายฝรั่งเศสสมัยนั้นด้วยซ้ำ'),
    ('สัตว์โลก', 'จิงโจ้เดินถอยหลังไม่ได้', true, 'จริง! โครงสร้างขาหลังและหางของจิงโจ้ไม่เอื้อให้เดินถอยหลังได้'),
    ('วิทยาศาสตร์', 'น้ำร้อนแข็งตัวเป็นน้ำแข็งได้เร็วกว่าน้ำเย็นในบางสภาวะ', true, 'จริง! ปรากฏการณ์นี้เรียกว่า Mpemba Effect พบว่าในบางเงื่อนไข น้ำอุ่นแข็งตัวเร็วกว่าน้ำเย็นได้จริง'),
    ('อาหาร', 'กล้วยเป็นผลไม้ตระกูลเบอร์รี ในขณะที่สตรอว์เบอร์รีไม่ใช่เบอร์รีตามหลักพฤกษศาสตร์', true, 'จริง! กล้วยจัดเป็นเบอร์รี ส่วนสตรอว์เบอร์รีมีเมล็ดอยู่ด้านนอกผล จึงไม่เข้าเกณฑ์เบอร์รีที่แท้จริง'),
    ('อวกาศ', 'ดาวเสาร์มีความหนาแน่นน้อยกว่าน้ำ จึงสามารถลอยน้ำได้ในทางทฤษฎี', true, 'จริง! ดาวเสาร์มีความหนาแน่นเฉลี่ยประมาณ 0.69 g/cm³ ต่ำกว่าน้ำ หากมีมหาสมุทรใหญ่พอ ดาวเสาร์จะลอยน้ำได้จริง'),
    ('ประวัติศาสตร์ไทย', 'ธงไตรรงค์ของไทยเริ่มใช้อย่างเป็นทางการในสมัยรัชกาลที่ 6', true, 'จริง! รัชกาลที่ 6 ทรงประกาศใช้ธงไตรรงค์เป็นธงชาติอย่างเป็นทางการเมื่อ พ.ศ. 2460'),
    ('สัตว์โลก', 'หมาป่าโตเต็มวัยสามารถวิ่งได้ไกลกว่ามาราธอนในหนึ่งวัน', true, 'จริง! หมาป่าสามารถเดินทางล่าเหยื่อได้ไกลถึง 50 กม.ต่อวันในบางกรณี มากกว่าระยะมาราธอน'),
    ('เทคโนโลยี', 'รหัสผ่านที่มีความยาวมากแต่ใช้คำง่ายๆ ต่อกัน ปลอดภัยน้อยกว่ารหัสสั้นที่มีอักขระพิเศษเสมอ', false, 'มั่ว! ความยาวของรหัสผ่านมีผลต่อความปลอดภัยมากกว่าความซับซ้อน วลีที่ยาวแต่จำง่ายมักปลอดภัยกว่ารหัสสั้นที่ซับซ้อน'),
    ('ร่างกายมนุษย์', 'ผู้ใหญ่มีจำนวนกระดูกน้อยกว่าทารกแรกเกิด', true, 'จริง! ทารกแรกเกิดมีกระดูกราว 300 ชิ้น แต่เมื่อโตเป็นผู้ใหญ่ กระดูกบางชิ้นจะเชื่อมรวมกัน เหลือประมาณ 206 ชิ้น'),
    ('วิทยาศาสตร์', 'แสงจากดวงอาทิตย์ใช้เวลาเดินทางมาถึงโลกประมาณ 8 นาที', true, 'จริง! แสงอาทิตย์ใช้เวลาประมาณ 8 นาที 20 วินาที กว่าจะมาถึงโลก')
  ) as v(cat_name, text, answer, explain)
join cat on cat.name = v.cat_name
where not exists (
  select 1 from questions q2
  where q2.game_id = 'truth-or-lie' and q2.text = v.text
);